"""Phantom specimen: a synthetic "SEM video" signal generated by the DAQ itself.

When ``DAQConfig.phantom_output`` names an aux analog output (e.g. ``"aux0"``
= AO2 on the USB-6363), every hardware-timed stream also drives that output
with the intensity of a test chart at the *commanded* beam position, sample
for sample on the scan clock.  Wire it to the video input (AO2 → AI0) and the
complete imaging chain – waveform generation, sample clock, AO→AI latency,
field of view, beam shift, rotation, averaging, noise – runs on real
hardware against a known ground truth.  While the beam is blanked the phantom
outputs ``blank_v`` (no beam, no signal).

The chart lives in *deflection-voltage* space (±``extent_v``), so it is fixed
to the DAQ field: changing the scan width zooms into it, a beam shift moves
across it.  It is deliberately asymmetric (orientation marks in every
quadrant) so mirrored or rotated axes are obvious.
"""
from __future__ import annotations

import functools

import numpy as np

__all__ = ["PhantomSpecimen", "make_test_chart"]


def _disk(xx, yy, cx, cy, r, px):
    d = np.hypot(xx - cx, yy - cy)
    return np.clip((r - d) / px + 0.5, 0.0, 1.0)


def _box(xx, yy, x0, x1, y0, y1, px):
    fx = np.clip(np.minimum(xx - x0, x1 - xx) / px + 0.5, 0, 1)
    fy = np.clip(np.minimum(yy - y0, y1 - yy) / px + 0.5, 0, 1)
    return fx * fy


def make_test_chart(n: int = 2048, seed: int = 3) -> np.ndarray:
    """(n, n) float32 test chart in [0, 1]; row 0 = top (+y), coordinates u, v ∈ [-1, 1].

    * background 0.15 with a coarse grid every 0.25 and concentric rings every 0.2;
    * a 36-spoke Siemens star in the centre (resolution / focus);
    * line gratings with periods from 0.08 down to 0.005 (resolution at each zoom);
    * orientation marks: an "F" (upper left), a square (upper right),
      a triangle (lower left) and two dots (lower right);
    * random particles (gaussian blobs) for texture.
    """
    px = 2.0 / n
    c = (np.arange(n) + 0.5) * px - 1.0
    u, v = np.meshgrid(c, c[::-1])  # v increases upwards: row 0 is the top
    img = np.full((n, n), 0.15, dtype=np.float32)
    # grid and rings
    for g in np.arange(-1.0, 1.01, 0.25):
        img += 0.25 * (np.abs(u - g) < 0.6 * px) + 0.25 * (np.abs(v - g) < 0.6 * px)
    r = np.hypot(u, v)
    for rr in np.arange(0.2, 1.01, 0.2):
        img += 0.2 * np.clip(1.2 - np.abs(r - rr) / px, 0, 1)
    # Siemens star
    ang = np.arctan2(v, u)
    star = (r < 0.15) & (np.sin(36 / 2 * ang) > 0)
    img = np.where(star, 0.85, img)
    # gratings (vertical bars, periods halving), right of centre, below the axis
    x0 = 0.3
    for k, period in enumerate([0.08, 0.04, 0.02, 0.01, 0.005]):
        y_top = -0.05 - k * 0.07
        band = (v < y_top) & (v > y_top - 0.05) & (u > x0) & (u < x0 + 0.5)
        img = np.where(band, np.where(np.sin(2 * np.pi * (u - x0) / period) > 0, 0.8, 0.2), img)
    # orientation marks
    F = _box(u, v, -0.75, -0.70, 0.45, 0.75, px)  # vertical stroke
    F = np.maximum(F, _box(u, v, -0.75, -0.55, 0.70, 0.75, px))  # top bar
    F = np.maximum(F, _box(u, v, -0.75, -0.60, 0.58, 0.63, px))  # middle bar
    sq = _box(u, v, 0.55, 0.75, 0.55, 0.75, px)
    tri = ((u > -0.75) & (u < -0.55) & (v < -0.55) & (v > -0.75) & (v - (-0.75) < (u + 0.75))).astype(np.float32)
    dots = np.maximum(_disk(u, v, 0.6, -0.65, 0.05, px), _disk(u, v, 0.72, -0.65, 0.05, px))
    for m in (F, sq, tri, dots):
        img = np.maximum(img, 0.95 * m)
    # particles (each evaluated in its own ±4σ window only)
    rng = np.random.default_rng(seed)
    for _ in range(80):
        cx, cy = rng.uniform(-0.95, 0.95, 2)
        rad = rng.uniform(0.004, 0.02)
        c0 = max(0, int((cx - 4 * rad + 1.0) / px))
        c1 = min(n, int((cx + 4 * rad + 1.0) / px) + 1)
        r0 = max(0, int((1.0 - (cy + 4 * rad)) / px))
        r1 = min(n, int((1.0 - (cy - 4 * rad)) / px) + 1)
        uu, vv = u[r0:r1, c0:c1], v[r0:r1, c0:c1]
        img[r0:r1, c0:c1] += 0.35 * np.exp(-((uu - cx) ** 2 + (vv - cy) ** 2) / (2 * rad * rad))
    return np.clip(img, 0.0, 1.0).astype(np.float32)


@functools.lru_cache(maxsize=2)
def _default_chart(n: int = 2048) -> np.ndarray:
    a = make_test_chart(n)
    a.setflags(write=False)  # shared, read-only
    return a


class PhantomSpecimen:
    """Maps commanded deflection voltages to a synthetic video voltage.

    Parameters
    ----------
    image:      (n, n) array in [0, 1] (row 0 = top); default :func:`make_test_chart`.
    extent_v:   the image spans ±extent_v on both deflection axes (set to the AO
                limit so it fills the DAQ field).
    low_v, high_v: output voltage for image value 0 and 1.
    blank_v:    output while the beam is blanked.
    noise_v:    rms of synthetic white noise added to every sample (detector
                noise; makes the √(samples per pixel) averaging visible).
    """

    def __init__(
        self,
        image: np.ndarray | None = None,
        extent_v: float = 5.0,
        low_v: float = 0.0,
        high_v: float = 4.0,
        blank_v: float = 0.0,
        noise_v: float = 0.0,
        seed: int | None = 0,
    ):
        self.image = np.ascontiguousarray(_default_chart() if image is None else image, dtype=np.float32)
        if self.image.ndim != 2:
            raise ValueError("phantom image must be 2-D")
        self.extent_v = float(extent_v)
        self.low_v, self.high_v, self.blank_v = float(low_v), float(high_v), float(blank_v)
        self.noise_v = float(noise_v)
        self._rng = np.random.default_rng(seed)
        ny, nx = self.image.shape
        # value lookup table in volts, plus one background pixel for "outside"
        self._lut = (self.low_v + (self.high_v - self.low_v) * self.image).ravel()
        self._bg = self.low_v + (self.high_v - self.low_v) * float(np.median(self.image[:4]))
        self._nx, self._ny = nx, ny

    def intensity_v(self, x_v: np.ndarray, y_v: np.ndarray) -> np.ndarray:
        """Noise-free output (V) at commanded positions (nearest pixel of the chart)."""
        x_v = np.asarray(x_v, dtype=np.float64)
        y_v = np.asarray(y_v, dtype=np.float64)
        L = self.extent_v
        col = np.floor((x_v + L) * (self._nx / (2 * L))).astype(np.int64)
        row = np.floor((L - y_v) * (self._ny / (2 * L))).astype(np.int64)
        inside = (col >= 0) & (col < self._nx) & (row >= 0) & (row < self._ny)
        idx = np.where(inside, row * self._nx + col, 0)
        return np.where(inside, self._lut[idx], self._bg)

    def expected_image(self, config, calibration) -> np.ndarray:
        """The noise-free image a raster scan with *config* should show (pixel centres).

        *config* is a :class:`~easyebl.imaging.RasterConfig` (field µm, rotation,
        beam shift), *calibration* the :class:`~easyebl.core.FieldCalibration`
        that maps it to volts – exactly what the scan commands.
        """
        nx, ny = config.nx, config.ny
        pw, ph = config.pixel_size_um
        u = -config.width_um / 2 + (np.arange(nx) + 0.5) * pw
        v = config.height / 2 - (np.arange(ny) + 0.5) * ph
        uu, vv = np.meshgrid(u, v)
        c, s = np.cos(config.rotation_rad), np.sin(config.rotation_rad)
        x = config.center_um[0] + c * uu - s * vv
        y = config.center_um[1] + s * uu + c * vv
        volts = calibration.um_to_volts(np.column_stack([x.ravel(), y.ravel()]), check=False)
        return self.intensity_v(volts[:, 0], volts[:, 1]).reshape(ny, nx)

    def output(self, x_v: np.ndarray, y_v: np.ndarray, blank: np.ndarray) -> np.ndarray:
        """Per-sample phantom output for one chunk (what goes to the aux AO channel)."""
        out = self.intensity_v(x_v, y_v)
        out = np.where(blank, self.blank_v, out)
        if self.noise_v > 0:
            out = out + self._rng.normal(0.0, self.noise_v, out.shape)
        return out
